        case 5: return std::make_unique<Holder<GtkAppChooserWidget>>(d, s, win, gc, st, x, y, w, h);
        case 6: return std::make_unique<Holder<GtkApplicationWindow>>(d, s, win, gc, st, x, y, w, h);
        case 7: return std::make_unique<Holder<GtkAspectFrame>>(d, s, win, gc, st, x, y, w, h);
        case 8: return std::make_unique<Holder<GtkAssistant>>(d, s, win, gc, st, x, y, w, h);
        case 9: return std::make_unique<Holder<GtkBox>>(d, s, win, gc, st, x, y, w, h);
        case 10: return std::make_unique<Holder<GtkButton>>(d, s, win, gc, st, x, y, w, h);
        case 11: return std::make_unique<Holder<GtkButtonBox>>(d, s, win, gc, st, x, y, w, h);
        case 12: return std::make_unique<Holder<GtkCalendar>>(d, s, win, gc, st, x, y, w, h);
        case 13: return std::make_unique<Holder<GtkCellView>>(d, s, win, gc, st, x, y, w, h);
        case 14: return std::make_unique<Holder<GtkCenterBox>>(d, s, win, gc, st, x, y, w, h);
        case 15: return std::make_unique<Holder<GtkCheckButton>>(d, s, win, gc, st, x, y, w, h);
